-- Re-seeds the media workflow-I/O kinds after the media-identity change:
--   generated_video_set  <- GenerateVideoOutput   (GeneratedVideo gained file_id/cdn_url/signed_url)
--   generated_audio      <- TextToSpeechOutput    (gained file_id/audio_cdn_url/audio_signed_url)
--
-- WHY: the media-durability law says internally we pass the file_id — a URL is a
-- handoff, never an identity. Both nodes' producers knew the cld_files id at
-- persist time and dropped it, so a consumer that outlived a signed URL had
-- nothing to re-mint from. `GeneratedImage` already carried it; these two now do
-- too, and a kind's schema is only ever its model's model_json_schema() output.
-- Supersedes the schemas seeded by content_ir_seed_media_io_kinds.sql (which is
-- left untouched as the record of what landed then).
--
-- Guarded, not unconditional: each statement is a no-op when the row already
-- holds the new shape, so a re-run cannot revert anything.

update content_ir.kind_definition
   set emitted_json_schema = $mtx${"$defs": {"AiModelUsage": {"additionalProperties": false, "description": "Per-model token/cost breakdown \u2014 one entry in :class:`AiUsage.models`.\n\nClosed shape, one canonical key-set across every producer. ``cost_usd``\nmatches the top-level ``AiUsage.cost_usd`` (this unified a prior divergence\nwhere graph_nodes wrote ``cost`` while the podcast aggregator wrote\n``cost_usd``). ``api`` / ``request_count`` default to ``\"\"`` / ``0`` for\nproducers that don't track them.", "properties": {"input_tokens": {"default": 0, "title": "Input Tokens", "type": "integer"}, "output_tokens": {"default": 0, "title": "Output Tokens", "type": "integer"}, "total_tokens": {"default": 0, "title": "Total Tokens", "type": "integer"}, "cost_usd": {"default": 0.0, "title": "Cost Usd", "type": "number"}, "request_count": {"default": 0, "title": "Request Count", "type": "integer"}, "api": {"default": "", "title": "Api", "type": "string"}}, "title": "AiModelUsage", "type": "object"}, "AiUsage": {"description": "Aggregated token / cost usage for the run.\n\nEvery constructor in the package (``_extract_usage`` below and the\npodcast pipeline's stage aggregators) sets only the declared fields, so\nthe model is closed \u2014 no ``extra=\"allow\"``. Per-model breakdown values are\ntyped as :class:`AiModelUsage`: the two producer shapes were unified onto\none canonical key-set (``cost_usd`` everywhere), so this is a precise\ncontract, not an open ``dict[str, JsonValue]``.", "properties": {"input_tokens": {"default": 0, "description": "Total input tokens billed across the run.", "title": "Input Tokens", "type": "integer"}, "output_tokens": {"default": 0, "description": "Total output tokens billed across the run.", "title": "Output Tokens", "type": "integer"}, "total_tokens": {"default": 0, "description": "Combined input and output token count across the run.", "title": "Total Tokens", "type": "integer"}, "cost_usd": {"default": 0.0, "description": "Total estimated provider cost in US dollars.", "title": "Cost Usd", "type": "number"}, "models": {"additionalProperties": {"$ref": "#/$defs/AiModelUsage"}, "description": "Per-model usage breakdown keyed by canonical model name.", "title": "Models", "type": "object"}}, "title": "AiUsage", "type": "object"}, "GeneratedVideo": {"properties": {"file_id": {"anyOf": [{"type": "string"}, {"type": "null"}], "default": null, "description": "cld_files id of the generated video \u2014 the durable handle. Pass this between nodes and re-mint any URL from it; never store a signed URL.", "title": "File Id"}, "path": {"anyOf": [{"type": "string"}, {"type": "null"}], "default": null, "description": "Local filesystem path, when the provider wrote one.", "title": "Path"}, "url": {"anyOf": [{"type": "string"}, {"type": "null"}], "default": null, "description": "Inline-render URL for the video. Permanent for a public video, short-lived for a personal one \u2014 re-resolve from file_id on expiry.", "title": "Url"}, "cdn_url": {"anyOf": [{"type": "string"}, {"type": "null"}], "default": null, "description": "Permanent CDN URL, present only when the video is public.", "title": "Cdn Url"}, "signed_url": {"anyOf": [{"type": "string"}, {"type": "null"}], "default": null, "description": "Expiring inline URL, present only for a non-public video.", "title": "Signed Url"}, "mime_type": {"anyOf": [{"type": "string"}, {"type": "null"}], "default": null, "description": "Canonical MIME type of the encoded video.", "title": "Mime Type"}, "duration_seconds": {"anyOf": [{"type": "number"}, {"type": "null"}], "default": null, "description": "Video duration in seconds, when the provider reports one.", "title": "Duration Seconds"}}, "title": "GeneratedVideo", "type": "object"}}, "additionalProperties": false, "properties": {"videos": {"description": "Every video the provider returned, in order.", "items": {"$ref": "#/$defs/GeneratedVideo"}, "title": "Videos", "type": "array"}, "count": {"default": 0, "description": "How many videos were generated.", "title": "Count", "type": "integer"}, "model": {"description": "Video model id that produced the videos.", "title": "Model", "type": "string"}, "usage": {"$ref": "#/$defs/AiUsage"}}, "required": ["model"], "title": "GenerateVideoOutput", "type": "object"}$mtx$::jsonb,
       metadata = metadata || $mtx${"description": "One or more generated video clips with their canonical file identity and durable URLs."}$mtx$::jsonb
 where organization_id = '39c38960-d30c-4840-b0c1-c9960de95582'
   and kind = 'generated_video_set'
   and deleted_at is null
   and emitted_json_schema is distinct from $mtx${"$defs": {"AiModelUsage": {"additionalProperties": false, "description": "Per-model token/cost breakdown \u2014 one entry in :class:`AiUsage.models`.\n\nClosed shape, one canonical key-set across every producer. ``cost_usd``\nmatches the top-level ``AiUsage.cost_usd`` (this unified a prior divergence\nwhere graph_nodes wrote ``cost`` while the podcast aggregator wrote\n``cost_usd``). ``api`` / ``request_count`` default to ``\"\"`` / ``0`` for\nproducers that don't track them.", "properties": {"input_tokens": {"default": 0, "title": "Input Tokens", "type": "integer"}, "output_tokens": {"default": 0, "title": "Output Tokens", "type": "integer"}, "total_tokens": {"default": 0, "title": "Total Tokens", "type": "integer"}, "cost_usd": {"default": 0.0, "title": "Cost Usd", "type": "number"}, "request_count": {"default": 0, "title": "Request Count", "type": "integer"}, "api": {"default": "", "title": "Api", "type": "string"}}, "title": "AiModelUsage", "type": "object"}, "AiUsage": {"description": "Aggregated token / cost usage for the run.\n\nEvery constructor in the package (``_extract_usage`` below and the\npodcast pipeline's stage aggregators) sets only the declared fields, so\nthe model is closed \u2014 no ``extra=\"allow\"``. Per-model breakdown values are\ntyped as :class:`AiModelUsage`: the two producer shapes were unified onto\none canonical key-set (``cost_usd`` everywhere), so this is a precise\ncontract, not an open ``dict[str, JsonValue]``.", "properties": {"input_tokens": {"default": 0, "description": "Total input tokens billed across the run.", "title": "Input Tokens", "type": "integer"}, "output_tokens": {"default": 0, "description": "Total output tokens billed across the run.", "title": "Output Tokens", "type": "integer"}, "total_tokens": {"default": 0, "description": "Combined input and output token count across the run.", "title": "Total Tokens", "type": "integer"}, "cost_usd": {"default": 0.0, "description": "Total estimated provider cost in US dollars.", "title": "Cost Usd", "type": "number"}, "models": {"additionalProperties": {"$ref": "#/$defs/AiModelUsage"}, "description": "Per-model usage breakdown keyed by canonical model name.", "title": "Models", "type": "object"}}, "title": "AiUsage", "type": "object"}, "GeneratedVideo": {"properties": {"file_id": {"anyOf": [{"type": "string"}, {"type": "null"}], "default": null, "description": "cld_files id of the generated video \u2014 the durable handle. Pass this between nodes and re-mint any URL from it; never store a signed URL.", "title": "File Id"}, "path": {"anyOf": [{"type": "string"}, {"type": "null"}], "default": null, "description": "Local filesystem path, when the provider wrote one.", "title": "Path"}, "url": {"anyOf": [{"type": "string"}, {"type": "null"}], "default": null, "description": "Inline-render URL for the video. Permanent for a public video, short-lived for a personal one \u2014 re-resolve from file_id on expiry.", "title": "Url"}, "cdn_url": {"anyOf": [{"type": "string"}, {"type": "null"}], "default": null, "description": "Permanent CDN URL, present only when the video is public.", "title": "Cdn Url"}, "signed_url": {"anyOf": [{"type": "string"}, {"type": "null"}], "default": null, "description": "Expiring inline URL, present only for a non-public video.", "title": "Signed Url"}, "mime_type": {"anyOf": [{"type": "string"}, {"type": "null"}], "default": null, "description": "Canonical MIME type of the encoded video.", "title": "Mime Type"}, "duration_seconds": {"anyOf": [{"type": "number"}, {"type": "null"}], "default": null, "description": "Video duration in seconds, when the provider reports one.", "title": "Duration Seconds"}}, "title": "GeneratedVideo", "type": "object"}}, "additionalProperties": false, "properties": {"videos": {"description": "Every video the provider returned, in order.", "items": {"$ref": "#/$defs/GeneratedVideo"}, "title": "Videos", "type": "array"}, "count": {"default": 0, "description": "How many videos were generated.", "title": "Count", "type": "integer"}, "model": {"description": "Video model id that produced the videos.", "title": "Model", "type": "string"}, "usage": {"$ref": "#/$defs/AiUsage"}}, "required": ["model"], "title": "GenerateVideoOutput", "type": "object"}$mtx$::jsonb;

update content_ir.kind_example e
   set data = $mtx${"videos": [{"file_id": "28805c30-3848-40eb-8f51-b7d34ea4ea15", "url": "https://cdn.matrxserver.com/4cf62e4e-2679-484f-b652-034e697418df/28805c30-3848-40eb-8f51-b7d34ea4ea15?v=d7a1a053", "cdn_url": "https://cdn.matrxserver.com/4cf62e4e-2679-484f-b652-034e697418df/28805c30-3848-40eb-8f51-b7d34ea4ea15?v=d7a1a053", "mime_type": "video/mp4", "duration_seconds": 8.0}], "count": 1, "model": "veo-3", "usage": {"cost_usd": 0.75}}$mtx$::jsonb,
       kind_version = kd.version
  from content_ir.kind_definition kd
 where e.kind_definition_id = kd.id
   and kd.organization_id = '39c38960-d30c-4840-b0c1-c9960de95582'
   and kd.kind = 'generated_video_set'
   and kd.deleted_at is null
   and e.is_canonical
   and e.deleted_at is null
   and e.data is distinct from $mtx${"videos": [{"file_id": "28805c30-3848-40eb-8f51-b7d34ea4ea15", "url": "https://cdn.matrxserver.com/4cf62e4e-2679-484f-b652-034e697418df/28805c30-3848-40eb-8f51-b7d34ea4ea15?v=d7a1a053", "cdn_url": "https://cdn.matrxserver.com/4cf62e4e-2679-484f-b652-034e697418df/28805c30-3848-40eb-8f51-b7d34ea4ea15?v=d7a1a053", "mime_type": "video/mp4", "duration_seconds": 8.0}], "count": 1, "model": "veo-3", "usage": {"cost_usd": 0.75}}$mtx$::jsonb;

